#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int S, T;
    cin >> S >> T;

    vector<vector<char>> adj(S + 1, vector<char>(S + 1, 0));

    for (int i = 0; i < T; ++i) {
        int X, Y;
        cin >> X >> Y;
        adj[X][Y] = 1;
        adj[Y][X] = 1;
    }

    int P;
    cin >> P;

    int answer = 0;

    for (int i = 0; i < P; ++i) {
        int N;
        cin >> N;

        int prev;
        cin >> prev;

        bool ok = true;

        for (int j = 1; j < N; ++j) {
            int cur;
            cin >> cur;

            if (!adj[prev][cur]) {
                ok = false;
            }

            prev = cur;
        }

        if (ok) {
            ++answer;
        }
    }

    cout << answer << '\n';

    return 0;
}
